import React from "react";
import { StatusBadge } from "../../index";
import "./VerticalClickableCard.scss";

export interface VerticalClickableCardProps {
  id?: string;
  cardType?: "elevated" | "filled" | "outline";
  types?: "Card01" | "Card02";
  showImage?: boolean;
  imageUrl?: string;
  showStatusBadge?: boolean;
  badgeText?: string;
  title?: string;
  subText?: string;
  description?: string;
  onCardClick?: () => void;
  disabled?: boolean;
}

const VerticalClickableCard: React.FC<VerticalClickableCardProps> = ({
  id,
  cardType = "elevated",
  types = "Card01",  
  showImage = true,
  imageUrl,
  showStatusBadge = true,
  badgeText,
  title,
  subText,
  description,
  onCardClick,
  disabled = false,
}) => {
  const showimagetop = types === "Card01";

  return (
    <div
      className={`mpa-clickcardLayoutWrapper ${disabled ? "disabled" : ""} ${cardType} `}
      onClick={onCardClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onCardClick?.();
        }
      }}
    >
      {showimagetop && showImage && (
        <div className="mpa-clickcardImageContainer full-width">
          <img
            src={imageUrl}
            alt={(id ?? "") + " Description of image"}
            className="mpa-clickcardImage"
          />
        </div>
      )}

      <div className="mpa-clickcardSupportContainer">
        <div className="mpa-clickcardSupportTextContent">
          {showStatusBadge && (
            <div className="mpa-clickcardSupportBadgeContainer">
              <StatusBadge
                shape="semi-rounded"                
                id="statusBadgeId"
                size="small"
                label={badgeText}
                colour="surface"
              />
            </div>
          )}

          <div className="mpa-clickcardSupportTitle">{title}</div>
          <div className="mpa-clickcardSupportsubTitle">{subText}</div>
          <div className="mpa-clickcardSupportDescription text-multiline-ellipsis">
            {description}
          </div>
        </div>
      </div>

      {!showimagetop && showImage && (
        <div className="mpa-clickcardImageContainer full-width">
          <img
            src={imageUrl}
            alt={(id ?? "") + " Description of image"}
            className="mpa-clickcardImage"
          />
        </div>
      )}
    </div>
  );
};

export default VerticalClickableCard;